SELECT M.sys_id AS "sysId", M.surv_id AS "survId", M.sys_se_cd AS "sysSeCd", M.surv_nm AS "survNm", M.surv_ver AS "survVer", M.template_yn AS "templateYn", M.use_yn AS "useYn", M.start_dt AS "startDt", M.end_dt AS "endDt", M.frst_rgstr_id AS "frstRgstrId", M.frst_reg_dt AS "frstRegDt", (SELECT user_nm FROM TN_MEM_M001 U WHERE U.sys_id = M.sys_id AND U.user_id = M.frst_rgstr_id) AS "frstRgstrNm" FROM TN_SURVEY_M001 M WHERE M.sys_id = #{sysId} AND M.del_yn = 'N'
AND M.template_yn = #{templateYn}
AND M.surv_nm LIKE CONCAT('%', #{survNm}, '%')
AND M.surv_id LIKE CONCAT('%', #{survIdSearch}, '%')
ORDER BY M.surv_id DESC
LIMIT #{offset}, #{limit}

