mapper.select:
SELECT
    M.sys_id AS "sysId", M.surv_id AS "survId", M.sys_se_cd AS "sysSeCd", M.surv_nm AS "survNm",
    M.use_yn AS "useYn", M.start_dt AS "startDt", M.end_dt AS "endDt",
    M.frst_rgstr_id AS "frstRgstrId", M.frst_reg_dt AS "frstRegDt",
    (SELECT COUNT(*) FROM TN_SURVEY_P001 P WHERE P.sys_id = M.sys_id AND P.surv_id = M.surv_id) AS "respCnt"
FROM TN_SURVEY_M001 M
WHERE M.sys_id = #{sysId} AND M.template_yn = 'N' AND M.del_yn = 'N'

    AND M.sys_se_cd = #{sysSeCd}


    AND M.surv_nm LIKE CONCAT('%', #{survNm}, '%')


    AND M.surv_id LIKE CONCAT('%', #{survIdSearch}, '%')


    AND M.use_yn = #{useYn}


     AND M.start_dt >= #{startDt} 


     AND M.end_dt <= #{endDt} 

ORDER BY M.surv_id DESC

    LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM TN_SURVEY_M001 M
WHERE M.sys_id = #{sysId} AND M.template_yn = 'N' AND M.del_yn = 'N'

    AND M.sys_se_cd = #{sysSeCd}


    AND M.surv_nm LIKE CONCAT('%', #{survNm}, '%')


    AND M.surv_id LIKE CONCAT('%', #{survIdSearch}, '%')


    AND M.use_yn = #{useYn}


     AND M.start_dt >= #{startDt} 


     AND M.end_dt <= #{endDt}
